const { useState, useEffect } = React;

function Search({ query }) {
  const [found, setFound] = useState(null);
  const [tick, setTick] = useState(0);

  useEffect(() => {
    setFound(null);
    fetch('/api/search?q=' + encodeURIComponent(query))
      .then((res) => res.json())
      .then((list) => setFound(list));
  }, [query, tick]);

  if (found === null) {
    return <p className="state">찾는 중…</p>;
  }

  return (
    <div>
      <p className="state">{query} · {found.length}개</p>
      {found.map((c) => <p className="course" key={c.id}>{c.name}</p>)}
      <button className="again" type="button" onClick={() => setTick(tick + 1)}>다시 불러오기</button>
    </div>
  );
}

const root = ReactDOM.createRoot(document.querySelector('#root'));

root.render(<Search query="리" />);
setTimeout(() => root.render(<Search query="자" />), 1500);

