const root = ReactDOM.createRoot(document.querySelector('#root'));

function waitFor(ok, whenLate) {
  const el = document.querySelector('#root');
  return new Promise((resolve) => {
    const startedAt = Date.now();
    const tick = () => {
      if (ok(el.textContent)) resolve(el.textContent);
      else if (Date.now() - startedAt > 2000) resolve(whenLate || el.textContent);
      else setTimeout(tick, 30);
    };
    tick();
  });
}

function search(query) {
  root.render(<Search query={query} />);
  return waitFor((t) => t.includes('찾는 중'), '다시 찾지 않았습니다')
    .then((r) => (r === '다시 찾지 않았습니다' ? r : waitFor((t) => t && !t.includes('찾는 중'))));
}

function again() {
  document.querySelector('.again').click();
  return waitFor((t) => t.includes('찾는 중'), '버튼이 아무 일도 하지 않았습니다')
    .then((r) => (r === '버튼이 아무 일도 하지 않았습니다' ? r : waitFor((t) => t && !t.includes('찾는 중'))));
}

